INSERT INTO public.curriculum_contents (id, area, eje, content, grade)
VALUES
('50000000-0000-0000-0000-0000000000000001', 'artes-visuales', 'producci-n-visual', 'Creación de imágenes efímeras y permanentes a partir de la observación visual y/o táctil, de la imaginación, de la memoria, el azar y el juego (según la propuesta de enseñanza).', 1),
('50000000-0000-0000-0000-0000000000000002', 'artes-visuales', 'producci-n-visual', 'Nombres y distintos modos de uso de las herramientas, soportes y materiales en una misma producción y en distintas producciones. Organización y cuidado del espacio y de los materiales.', 1),
('50000000-0000-0000-0000-0000000000000003', 'artes-visuales', 'producci-n-visual', 'Características y posibilidades de las formas: grandes, pequeñas, abiertas y cerradas, alargadas, redondeadas y angulosas o rectilíneas. Creación de formas mediante manchas, recortes, trazos y/o estampados, entre otras posibilidades.', 1),
('50000000-0000-0000-0000-0000000000000004', 'artes-visuales', 'producci-n-visual', 'El color en experiencias pictóricas. Exploración de las variaciones de un mismo tono a través de mezclas de pintura, de la superposición de capas de lápices, tizas u otros materiales. Organización, cuidados y distintos modos de uso de los pinceles, espátulas, lápices, etcétera.', 1),
('50000000-0000-0000-0000-0000000000000005', 'artes-visuales', 'producci-n-visual', 'Texturas táctiles y visuales, sus posibilidades descriptivas y expresivas. Diferentes calidades de las superficies: lisa/rugosa, brillante/mate, artificial/natural. Uso de las texturas en experiencias de monocopia, collagraph, collage, etcétera.', 1),
('50000000-0000-0000-0000-0000000000000006', 'artes-visuales', 'producci-n-visual', 'Posibilidades expresivo-narrativas que brindan los distintos soportes. Diversidad de tamaños, formatos y superficies (regulares / irregulares, grandes/medianos, claros/oscuros) y sus posibilidades de transformación.', 1),
('50000000-0000-0000-0000-0000000000000007', 'artes-visuales', 'producci-n-visual', 'Imagen múltiple: procedimientos simples que posibilitan la seriación de una forma o producción (estampación de elementos naturales o industriales, dibujo sobre papel carbónico, fotocopiado e intervención de las copias logradas). Juegos de intervención, intercambio y/o creación grupal a partir de las copias o estampas logradas.', 1),
('50000000-0000-0000-0000-0000000000000008', 'artes-visuales', 'producci-n-visual', 'Variados usos de las herramientas y materiales en una misma y en distintas producciones: organización y cuidado del espacio y materiales.', 1),
('50000000-0000-0000-0000-0000000000000009', 'artes-visuales', 'producci-n-visual', 'Aproximación a la noción de escultura. Exploración del volumen, peso, espacio y puntos de apoyo en modelados, construcciones, ensambles y/o encastres. Organización del espacio y de los materiales de trabajo en la creación de esculturas, relieves, máscaras, etc.', 1),
('50000000-0000-0000-0000-000000000000000a', 'artes-visuales', 'producci-n-visual', 'Exploración y resignificación de pequeños y medianos espacios (cajas, rincones, baldosas, entre otros), de objetos y elementos naturales mediante la creación de pequeñas instalaciones. Reconocimiento y uso de espacios abiertos, cerrados, ocupados, vacíos. Espacios y objetos cotidianos como recursos para el juego simbólico y la narración visual y multisensorial.', 1),
('50000000-0000-0000-0000-000000000000000b', 'artes-visuales', 'producci-n-visual', 'Posibilidades procedimentales en la producción escultórica: modelado, ensambles, bajorrelieves y/o encastres. Exploración de técnicas para crear y combinar formas: agregar, quitar, cortar, perforar, atar, encintar, pegar, etcétera.', 1),
('50000000-0000-0000-0000-000000000000000c', 'artes-visuales', 'producci-n-visual', 'Los materiales en la producción tridimensional: diferenciación entre elementos naturales (arcilla, ramas, cortezas, etc.) y materiales industriales (papel, cartón, plásticos) con los que se pueden crear esculturas e instalaciones. Criterios de clasificación, uso y guardado responsable que posibilitan la reutilización y la preservación del ambiente. EAI', 1),
('50000000-0000-0000-0000-000000000000000d', 'artes-visuales', 'producci-n-visual', 'La luz como material para la creación visual. Cambios de color y de intensidad de la luz natural y artificial mediante la exploración de filtros cromáticos traslúcidos en ventanas, linternas, proyectores, entre otras posibilidades.', 1),
('50000000-0000-0000-0000-000000000000000e', 'artes-visuales', 'apreciaci-n', 'Manifestación de ideas y sensaciones sobre las propias producciones y las de pares.', 1),
('50000000-0000-0000-0000-000000000000000f', 'artes-visuales', 'apreciaci-n', 'Percepción de entornos cercanos (la escuela, el barrio, la casa) mediante la vista, el tacto, el desplazamiento, el oído y/o el olfato. Identificación de la presencia del color, la forma y la textura en espacios próximos abiertos y cerrados.', 1),
('50000000-0000-0000-0000-0000000000000010', 'artes-visuales', 'apreciaci-n', 'Observación de creaciones locales (tejidos, grabados, pinturas, entre otras); identificación de algunas características expresivas y procedimentales.', 1),
('50000000-0000-0000-0000-0000000000000011', 'artes-visuales', 'apreciaci-n', 'Observación de cualidades estéticas, narrativas y visuales de obras creadas mediante diferentes disciplinas. Características distintivas de pinturas, esculturas, instalaciones, cerámicas, grabados y/o fotografías.', 1),
('50000000-0000-0000-0000-0000000000000012', 'artes-visuales', 'apreciaci-n', 'Manifestación de ideas y sensaciones personales sobre producciones visuales creadas en diferentes épocas y lugares del mundo. Aceptación de diferentes reflexiones en los intercambios grupales. ESI', 1),
('50000000-0000-0000-0000-0000000000000013', 'artes-visuales', 'apreciaci-n', 'Diferentes tiempos, actitudes y posibilidades corporales requeridas para la observación de producciones tridimensionales, bidimensionales, digitales (de cerca, de lejos, desde diversas ubicaciones, en quietud, en movimiento, etc.).', 1),
('50000000-0000-0000-0000-0000000000000014', 'artes-visuales', 'artes-visuales-en-contexto', 'Las obras de arte en contextos cotidianos. Reconocimiento de pinturas y esculturas en la vía pública, reproducciones de obras en el entorno familiar, producciones infantiles y/o artísticas en la escuela, entre otros.', 1),
('50000000-0000-0000-0000-0000000000000015', 'artes-visuales', 'artes-visuales-en-contexto', 'Características que diferencian las obras originales y de las reproducciones (impresas o digitales). ECD', 1),
('50000000-0000-0000-0000-0000000000000016', 'artes-visuales', 'artes-visuales-en-contexto', 'Las producciones artísticas tradicionales: rasgos distintivos de la pintura, el dibujo, el grabado, la cerámica y la escultura (importancia del saber técnico, perdurabilidad de los materiales y rol contemplativo del público, entre otros). EI', 1),
('50000000-0000-0000-0000-0000000000000017', 'artes-visuales', 'artes-visuales-en-contexto', 'Aproximación a los diversos modos de trabajo de los y las artistas: en sus talleres, en la vía pública, en ambientes donde realizan intervenciones.', 1),
('50000000-0000-0000-0000-0000000000000018', 'artes-visuales', 'artes-visuales-en-contexto', 'Formulación de preguntas y escucha atenta sobre relatos vinculados a las obras y a los procesos de creación en encuentros presenciales o virtuales con ceramistas, pintores/as, tejedoras/es, escultores/as, diseñadoras/es, grabadores/as, artesanas/os, escenógrafos/as y mascareros/as. EI', 1),
('50000000-0000-0000-0000-0000000000000019', 'artes-visuales', 'producci-n-visual', 'Creación de imágenes efímeras y permanentes a partir de la observación visual y/o táctil, de la imaginación, de la memoria, el azar y el juego (según la propuesta de enseñanza).', 2),
('50000000-0000-0000-0000-000000000000001a', 'artes-visuales', 'producci-n-visual', 'Nombres y distintos modos de uso de las herramientas, soportes y materiales en una misma producción y en distintas producciones. Organización y cuidado del espacio y de los materiales.', 2),
('50000000-0000-0000-0000-000000000000001b', 'artes-visuales', 'producci-n-visual', 'Exploración de las relaciones entre las formas y el espacio que las contiene: variaciones en la cantidad (muchas, pocas), posición (vertical, horizontal, inclinada) y ubicación (juntas, distanciadas, superpuestas, arriba, abajo, etcétera).', 2),
('50000000-0000-0000-0000-000000000000001c', 'artes-visuales', 'producci-n-visual', 'Texturas táctiles y visuales, sus posibilidades descriptivas y expresivas. Diferentes calidades de las superficies: lisa/rugosa, brillante/mate, artificial/natural. Uso de las texturas en experiencias de monocopia, collagraph, collage, etcétera.', 2),
('50000000-0000-0000-0000-000000000000001d', 'artes-visuales', 'producci-n-visual', 'El color en experiencias pictóricas. Obtención de distintos tonos mediante mezclas pigmentarias. Diversos usos de las herramientas pictóricas tradicionales y no convencionales. Selección y organización de colores en una gama o paleta.', 2),
('50000000-0000-0000-0000-000000000000001e', 'artes-visuales', 'producci-n-visual', 'Posibilidades expresivo-narrativas que brindan los distintos soportes. Diversidad de tamaños, formatos y superficies (regulares / irregulares, grandes/medianos, claros/oscuros) y sus posibilidades de transformación.', 2),
('50000000-0000-0000-0000-000000000000001f', 'artes-visuales', 'producci-n-visual', 'Imagen múltiple: procedimientos simples que posibilitan la seriación de una forma o producción (estampación de elementos naturales o industriales, dibujo sobre papel carbónico, fotocopiado e intervención de las copias logradas). Juegos de intervención, intercambio y/o creación grupal a partir de las copias o estampas logradas.', 2),
('50000000-0000-0000-0000-0000000000000020', 'artes-visuales', 'producci-n-visual', 'Variados usos de las herramientas y materiales en una misma y en distintas producciones: organización y cuidado del espacio y materiales.', 2),
('50000000-0000-0000-0000-0000000000000021', 'artes-visuales', 'producci-n-visual', 'Aproximación a la noción de escultura. Exploración del volumen, peso, espacio y puntos de apoyo en modelados, construcciones, ensambles y/o encastres. Organización del espacio y de los materiales de trabajo en la creación de esculturas, relieves, máscaras, etc.', 2),
('50000000-0000-0000-0000-0000000000000022', 'artes-visuales', 'producci-n-visual', 'Exploración y resignificación de pequeños y medianos espacios (cajas, rincones, baldosas, entre otros), de objetos y elementos naturales mediante la creación de pequeñas instalaciones. Reconocimiento y uso de espacios abiertos, cerrados, ocupados, vacíos. Espacios y objetos cotidianos como recursos para el juego simbólico y la narración visual y multisensorial.', 2),
('50000000-0000-0000-0000-0000000000000023', 'artes-visuales', 'producci-n-visual', 'Posibilidades procedimentales en la producción escultórica: modelado, ensambles, bajorrelieves y/o encastres. Exploración de técnicas para crear y combinar formas: agregar, quitar, cortar, perforar, atar, encintar, pegar, etcétera.', 2),
('50000000-0000-0000-0000-0000000000000024', 'artes-visuales', 'producci-n-visual', 'Los materiales en la producción tridimensional: diferenciación entre elementos naturales (arcilla, ramas, cortezas, etc.) y materiales industriales (papel, cartón, plásticos) con los que se pueden crear esculturas e instalaciones. Criterios de clasificación, uso y guardado responsable que posibilitan la reutilización y la preservación del ambiente. EAI', 2),
('50000000-0000-0000-0000-0000000000000025', 'artes-visuales', 'producci-n-visual', 'La luz como material para la creación visual. Proyección de la luz sobre objetos, texturas y/o el cuerpo y la exploración de las formas que generan las sombras. Cambios de tamaño en las formas según la distancia entre la luz y los objetos.', 2),
('50000000-0000-0000-0000-0000000000000026', 'artes-visuales', 'apreciaci-n', 'Manifestación de ideas y sensaciones sobre las propias producciones. Reflexión sobre los distintos usos del espacio, la forma, la textura, el color y la materialidad en imágenes propias y de pares (según focalización de la propuesta en cada caso).', 2),
('50000000-0000-0000-0000-0000000000000027', 'artes-visuales', 'apreciaci-n', 'Percepción multisensorial del entorno: reconocimiento de las variaciones que se producen en la percepción de formas, texturas, colores y líneas en diferentes momentos del día y/o del año. Valoración de la diversidad estética en la naturaleza y en la cultura del entorno. EAI', 2),
('50000000-0000-0000-0000-0000000000000028', 'artes-visuales', 'apreciaci-n', 'Observación y comparación de características expresivas, procedimentales y visuales en las creaciones tradicionales santafesinas: alfarería, textiles, cestería, talabartería, etc. EI', 2),
('50000000-0000-0000-0000-0000000000000029', 'artes-visuales', 'apreciaci-n', 'Observación de cualidades estéticas, narrativas y visuales de obras creadas mediante diferentes disciplinas. Características distintivas de pinturas, esculturas, instalaciones, cerámicas, grabados y/o fotografías.', 2),
('50000000-0000-0000-0000-000000000000002a', 'artes-visuales', 'apreciaci-n', 'Manifestación de ideas y sensaciones personales sobre producciones visuales creadas en diferentes épocas y lugares del mundo: relaciones entre esas sensaciones y los elementos visuales y las materialidades de las obras. Valoración de diferentes reflexiones en los intercambios grupales. ESI', 2),
('50000000-0000-0000-0000-000000000000002b', 'artes-visuales', 'apreciaci-n', 'Diferentes tiempos, actitudes y posibilidades corporales requeridas para la observación de producciones tridimensionales, bidimensionales, digitales (de cerca, de lejos, desde diversas ubicaciones, en quietud, en movimiento, etc.).', 2),
('50000000-0000-0000-0000-000000000000002c', 'artes-visuales', 'artes-visuales-en-contexto', 'La escuela como ámbito expositivo: pautas para el disfrute y cuidado de producciones propias y ajenas. CDP', 2),
('50000000-0000-0000-0000-000000000000002d', 'artes-visuales', 'artes-visuales-en-contexto', 'Pautas básicas para la interacción con las producciones artísticas en espacios expositivos. CDP, ECD', 2),
('50000000-0000-0000-0000-000000000000002e', 'artes-visuales', 'artes-visuales-en-contexto', 'Las producciones artísticas tradicionales: rasgos distintivos de la pintura, el dibujo, el grabado, la cerámica y la escultura (importancia del saber técnico, perdurabilidad de los materiales y rol contemplativo del público, entre otros). EI', 2),
('50000000-0000-0000-0000-000000000000002f', 'artes-visuales', 'artes-visuales-en-contexto', 'Aproximación a los diversos modos de trabajo de los y las artistas: en sus talleres, en la vía pública, en ambientes donde realizan intervenciones.', 2),
('50000000-0000-0000-0000-0000000000000030', 'artes-visuales', 'artes-visuales-en-contexto', 'Formulación de preguntas y escucha atenta sobre relatos vinculados a las obras y a los procesos de creación en encuentros presenciales o virtuales con ceramistas, pintores/as, tejedoras/es, escultores/as, diseñadoras/es, grabadores/as, artesanas/os, escenógrafos/as y mascareros/as. EI', 2),
('50000000-0000-0000-0000-0000000000000031', 'artes-visuales', 'producci-n-visual', 'Creación de imágenes efímeras y permanentes a partir de la observación visual y/o táctil, de la imaginación, de la memoria, el azar y el juego (según la propuesta de enseñanza).', 3),
('50000000-0000-0000-0000-0000000000000032', 'artes-visuales', 'producci-n-visual', 'Nombres y distintos modos de uso de las herramientas, soportes y materiales en una misma producción y en distintas producciones. Organización y cuidado del espacio y de los materiales.', 3),
('50000000-0000-0000-0000-0000000000000033', 'artes-visuales', 'producci-n-visual', 'La línea como contorno, la línea como forma, la línea construyendo texturas visuales. Exploración e identificación de distintos recorridos de la línea: rectas, curvas, espiraladas, quebradas y mixtas.', 3),
('50000000-0000-0000-0000-0000000000000034', 'artes-visuales', 'producci-n-visual', 'Exploración de distintos grados de saturación y de valor. Exploración de variaciones de dilución y/o empaste de la materia. Indagación sobre las distintas cualidades que tiene un mismo color al usarlo sobre un soporte claro y sobre un soporte oscuro, opaco y traslúcido, etc.', 3),
('50000000-0000-0000-0000-0000000000000035', 'artes-visuales', 'producci-n-visual', 'Reconocimiento y uso expresivo de las texturas propias de los materiales y de los elementos naturales, y de texturas logradas mediante procedimientos gráficos y pictóricos.', 3),
('50000000-0000-0000-0000-0000000000000036', 'artes-visuales', 'producci-n-visual', 'Posibilidades expresivo-narrativas que brindan los soportes en distintas posiciones (vertical/apaisado), y ubicaciones (sobre mesa, pared, piso, suspendido).', 3),
('50000000-0000-0000-0000-0000000000000037', 'artes-visuales', 'producci-n-visual', 'Imagen múltiple: procedimientos simples del grabado con adecuaciones técnicas (gofrado, collagraph, punta seca u otros procedimientos sin prensa). Noción de matriz y de estampa. Exploración de diferentes soportes, presiones y tipos de entintado para transformar la imagen original en el proceso de estampado.', 3),
('50000000-0000-0000-0000-0000000000000038', 'artes-visuales', 'producci-n-visual', 'Variados usos de las herramientas y materiales en una misma y en distintas producciones: organización y cuidado del espacio y materiales.', 3),
('50000000-0000-0000-0000-0000000000000039', 'artes-visuales', 'producci-n-visual', 'Exploración del equilibrio físico en esculturas erguidas. Juegos de ensamble y/o construcciones efímeras. Reconocimiento y uso de variados puntos de apoyo y sistemas de sujeción de las formas (pegamento, encastre, ataduras, magnetismo).', 3),
('50000000-0000-0000-0000-000000000000003a', 'artes-visuales', 'producci-n-visual', 'Transformación visual-simbólica de medianos y grandes espacios, objetos cotidianos y elementos naturales mediante la creación grupal de instalaciones móviles y/o permanentes.', 3),
('50000000-0000-0000-0000-000000000000003b', 'artes-visuales', 'producci-n-visual', 'Los materiales en la producción tridimensional: diferenciación entre elementos naturales (arcilla, ramas, cortezas, etc.) y materiales industriales (papel, cartón, plásticos) con los que se pueden crear esculturas e instalaciones. Criterios de clasificación, uso y guardado responsable que posibilitan la reutilización y la preservación del ambiente. EAI', 3),
('50000000-0000-0000-0000-000000000000003c', 'artes-visuales', 'producci-n-visual', 'Posibilidades procedimentales en la producción escultórica: plegados, ensambles y cartapestas. Pasajes de la bidimensión a la tridimensión mediante acciones con papel y/o cartón.', 3),
('50000000-0000-0000-0000-000000000000003d', 'artes-visuales', 'producci-n-visual', 'Aproximación a la fotografía. Uso de la fotografía como registro de ambientaciones y/o intervenciones lumínicas (proyecciones de luz, sombras, reflejos, etc.). ECD', 3),
('50000000-0000-0000-0000-000000000000003e', 'artes-visuales', 'producci-n-visual', 'La producción visual analógica y su transformación en entornos digitales: posibilidades estéticas que brindan las aplicaciones y softwares de edición de imágenes para producir variaciones de color, tamaño y soporte de producciones gráficas, pictóricas o escultóricas scanneadas o fotografiadas. ECD', 3),
('50000000-0000-0000-0000-000000000000003f', 'artes-visuales', 'apreciaci-n', 'Manifestación de ideas y sensaciones sobre las propias producciones. Reflexión sobre los distintos usos del espacio, la forma, la textura, el color y la materialidad en imágenes propias y de pares (según focalización de la propuesta en cada caso).', 3),
('50000000-0000-0000-0000-0000000000000040', 'artes-visuales', 'apreciaci-n', 'Percepción multisensorial del entorno: reconocimiento de las variaciones que se producen en la percepción de formas, texturas, colores y líneas en diferentes momentos del día y/o del año. Valoración de la diversidad estética en la naturaleza y en la cultura del entorno. EAI', 3),
('50000000-0000-0000-0000-0000000000000041', 'artes-visuales', 'apreciaci-n', 'Observación y comparación de características expresivas, procedimentales y visuales en las creaciones tradicionales santafesinas: alfarería, textiles, cestería, talabartería, etc. EI', 3),
('50000000-0000-0000-0000-0000000000000042', 'artes-visuales', 'apreciaci-n', 'Manifestación de ideas y sensaciones personales sobre producciones visuales creadas en diferentes épocas y lugares del mundo: relaciones entre esas sensaciones y los elementos visuales y las materialidades de las obras. Valoración de diferentes reflexiones en los intercambios grupales. ESI', 3),
('50000000-0000-0000-0000-0000000000000043', 'artes-visuales', 'apreciaci-n', 'Identificación de características materiales y expresivas en producciones visuales del pasado y del presente. Reflexión sobre la relación entre la representación y materialidad de la imagen y su contexto temporal. CDP', 3),
('50000000-0000-0000-0000-0000000000000044', 'artes-visuales', 'apreciaci-n', 'Diferentes tiempos, actitudes y posibilidades corporales requeridas para la observación de producciones tridimensionales, bidimensionales, digitales (de cerca, de lejos, desde diversas ubicaciones, en quietud, en movimiento, etc.).', 3),
('50000000-0000-0000-0000-0000000000000045', 'artes-visuales', 'artes-visuales-en-contexto', 'El reconocimiento de algunos aspectos básicos del montaje de las exposiciones: disposición de las obras, iluminación, títulos y textos, entre otros.', 3),
('50000000-0000-0000-0000-0000000000000046', 'artes-visuales', 'artes-visuales-en-contexto', 'Normas y recursos de accesibilidad en espacios expositivos que posibilitan el cuidado y disfrute de las producciones artísticas para todas las personas. CDP', 3),
('50000000-0000-0000-0000-0000000000000047', 'artes-visuales', 'artes-visuales-en-contexto', 'Las producciones artísticas contemporáneas: el uso de objetos y espacios cotidianos, lo efímero y lo participativo en las instalaciones e intervenciones.', 3),
('50000000-0000-0000-0000-0000000000000048', 'artes-visuales', 'artes-visuales-en-contexto', 'Formulación de preguntas y escucha atenta sobre relatos vinculados a las obras y a los procesos de creación en encuentros presenciales o virtuales con ceramistas, pintores/as, tejedoras/es, escultores/as, diseñadoras/es, grabadores/as, artesanas/os, escenógrafos/as y mascareros/as. EI', 3),
('50000000-0000-0000-0000-0000000000000049', 'artes-visuales', 'artes-visuales-en-contexto', 'Aproximación al trabajo de las y los artistas que utilizan tecnologías digitales en producciones bidimensionales, tridimensionales, audiovisuales. ECD', 3),
('50000000-0000-0000-0000-000000000000004a', 'artes-visuales', 'producci-n-visual', 'Creación de imágenes efímeras y permanentes a partir de la observación visual y/o táctil, de la imaginación, de la memoria, el azar y el juego.', 4),
('50000000-0000-0000-0000-000000000000004b', 'artes-visuales', 'producci-n-visual', 'Variados usos de las herramientas, soportes y materiales en una misma producción y en distintas producciones. Selección de materiales, soportes, herramientas y procedimientos según la intención expresiva.', 4),
('50000000-0000-0000-0000-000000000000004c', 'artes-visuales', 'producci-n-visual', 'Relaciones entre las formas y el espacio. Representación de la sensación de proximidad y lejanía mediante diversos indicadores espaciales: superposición de formas, gradación de tamaños, grosor de línea, entre otros.', 4),
('50000000-0000-0000-0000-000000000000004d', 'artes-visuales', 'producci-n-visual', 'Uso expresivo del color. Exploración del valor y la saturación mediante el uso del color puro, en mezclas, en recortes de distinto materiales y sobre diferentes soportes. Paletas limitadas y paletas amplias: relaciones de semejanza y de contraste entre colores.', 4),
('50000000-0000-0000-0000-000000000000004e', 'artes-visuales', 'producci-n-visual', 'Extracción de tintes naturales: decocción y machacado de especies vegetales tintóreas. Transformaciones del color a partir de la luz solar: antotipia con tintes naturales. Valoración y cuidado de la biodiversidad en relación con la producción artística. EAI', 4),
('50000000-0000-0000-0000-000000000000004f', 'artes-visuales', 'producci-n-visual', 'Aportes de las texturas táctiles y visuales a la imagen. Exploración de diversos procedimientos para la obtención y creación de texturas: frottage, estampación, grafismo, trama, collage.', 4),
('50000000-0000-0000-0000-0000000000000050', 'artes-visuales', 'producci-n-visual', 'Selección y creación de diversos soportes según la intención representativa y expresiva (apaisados, verticales, opacos, traslúcidos, regulares, irregulares, dípticos, polípticos, entre otros).', 4),
('50000000-0000-0000-0000-0000000000000051', 'artes-visuales', 'producci-n-visual', 'Creación de imágenes tridimensionales efímeras y permanentes, desde distintos puntos de partida según la propuesta: observación visual y/o táctil, imaginación, memoria, azar y juego.', 4),
('50000000-0000-0000-0000-0000000000000052', 'artes-visuales', 'producci-n-visual', 'Variados usos de las herramientas y materiales en una misma y en distintas producciones: selección de materiales, herramientas y procedimientos según la intención expresiva.', 4),
('50000000-0000-0000-0000-0000000000000053', 'artes-visuales', 'producci-n-visual', 'Características del espacio y la forma tridimensional (altura, anchura y profundidad) en la producción de esculturas y/o relieves. Posibilidades de diversos emplazamientos: volúmenes y/o relieves apoyados, suspendidos, amurados.', 4),
('50000000-0000-0000-0000-0000000000000054', 'artes-visuales', 'producci-n-visual', 'Procedimientos que posibilitan la transformación visual de los materiales secos (cartón, papel, tela, etc.) en la producción de esculturas y/o intervenciones: plegar, atar, apilar, modelar, encastrar, entrelazar.', 4),
('50000000-0000-0000-0000-0000000000000055', 'artes-visuales', 'producci-n-visual', 'Exploración de las características y posibilidades que brindan las instalaciones e intervenciones efímeras para resignificar los espacios de la escuela y/o el paisaje de su entorno. Uso y disposición espacial de elementos naturales e industriales según sus posibilidades simbólicas y expresivas.', 4),
('50000000-0000-0000-0000-0000000000000056', 'artes-visuales', 'producci-n-visual', 'Construcción de herramientas gráficas, pictóricas y/o escultóricas a partir de la recuperación de elementos industriales y/o naturales. Exploración de trazos, huellas, manchas e incisiones que posibilitan las herramientas creadas con ramas, lanas, telas, plásticos.', 4),
('50000000-0000-0000-0000-0000000000000057', 'artes-visuales', 'producci-n-visual', 'Recreación y resignificación de paisajes mediante el fotomontaje, la intervención de fotografías y/o reproducciones de obras propias y/o de diferentes artistas. Recursos visuales e iconográficos que transforman los espacios naturales o urbanos representados. ECD', 4),
('50000000-0000-0000-0000-0000000000000058', 'artes-visuales', 'apreciaci-n', 'Exploración multisensorial de diferentes espacios, formas, texturas y colores (sensaciones visuales, auditivas, olfativas, táctiles, entre otras). Uso de recursos o instrumentos que expanden la percepción (visores, lupas, ojos cerrados, descripciones sonoras, extensores, desplazamientos, etc.).', 4),
('50000000-0000-0000-0000-0000000000000059', 'artes-visuales', 'apreciaci-n', 'Reconocimiento de distintos usos de los elementos visuales, de los materiales, soportes y herramientas en producciones propias y de pares. Relaciones entre el punto de partida, las intenciones expresivas, las decisiones de proceso y la producción resultante.', 4),
('50000000-0000-0000-0000-000000000000005a', 'artes-visuales', 'apreciaci-n', 'Cualidades visuales del paisaje cercano. Percepción del espacio, las formas, los colores y las texturas del paisaje según distintas ubicaciones corporales y puntos de vista. Cambios que se producen a distintas horas del día y/o en distintos momentos del año.', 4),
('50000000-0000-0000-0000-000000000000005b', 'artes-visuales', 'apreciaci-n', 'Identificación de diversas intenciones expresivas y elementos visuales en las obras de paisajistas santafesinos (María Laura Schiavoni, Juan Mauricio Suhr, Ricardo Supisiche, Matías Molinas, entre otras/os). Reconocimiento de diferentes tipos de encuadres y vistas, de paletas de color descriptivas o imaginativas y de formas naturalistas o estilizadas.', 4),
('50000000-0000-0000-0000-000000000000005c', 'artes-visuales', 'apreciaci-n', 'Reconocimiento de distintos usos de los elementos visuales en obras tradicionales y contemporáneas de distintos países. Construcción de significados ante diferentes producciones.', 4),
('50000000-0000-0000-0000-000000000000005d', 'artes-visuales', 'apreciaci-n', 'Diversidad estética en paisajes creados en diferentes épocas y con distintas búsquedas estéticas (paisajes romanticistas, impresionistas, fauvistas, entre otros). Características de espacio, forma, colores, textura, diversidad de materialidades y formatos en las representaciones de paisajes urbanos y naturales. EI', 4),
('50000000-0000-0000-0000-000000000000005e', 'artes-visuales', 'apreciaci-n', 'Land art y site specific. Corrientes artísticas en las que el ambiente o espacio arquitectónico es intervenido para producir metáforas o reflexiones sobre las relaciones entre el ser humano y la naturaleza, la crisis ambiental, la biodiversidad, entre otras cuestiones. EAI', 4),
('50000000-0000-0000-0000-000000000000005f', 'artes-visuales', 'apreciaci-n', 'Participación activa en encuentros presenciales o virtuales con artistas y/o creadores tales como ceramistas, pintores/as, tejedores/as, escultores/as, diseñadores, grabadores, artesanos, escenógrafos y/o mascareros. EI', 4),
('50000000-0000-0000-0000-0000000000000060', 'artes-visuales', 'artes-visuales-en-contexto', 'Las funciones sociales de los museos físicos y/o virtuales: preservar, democratizar y activar el patrimonio artístico. CDP', 4),
('50000000-0000-0000-0000-0000000000000061', 'artes-visuales', 'artes-visuales-en-contexto', 'Agentes culturales que trabajan en y para los museos u otros espacios expositivos: montajistas, guías, restauradores/as, etcétera.', 4),
('50000000-0000-0000-0000-0000000000000062', 'artes-visuales', 'artes-visuales-en-contexto', 'Recursos de exhibición y cuidado de las producciones propias y de pares en el ámbito escolar: elecciones grupales sobre la disposición de las creaciones, construcción de títulos y textos breves, recursos de accesibilidad, entre otras posibilidades. CDP', 4),
('50000000-0000-0000-0000-0000000000000063', 'artes-visuales', 'artes-visuales-en-contexto', 'El paisaje como género artístico (en la pintura, el dibujo, el grabado, la fotografía, etc.). Diferentes ideas de naturaleza y de ciudad en obras de arte clásicas, modernas y contemporáneas. EAI', 4),
('50000000-0000-0000-0000-0000000000000064', 'artes-visuales', 'artes-visuales-en-contexto', 'Diferentes funciones de la representación del paisaje: el paisaje documental (Florián Paucke, los pintores viajeros del siglo XIX, entre otros) y el paisaje artístico (los grupos Litoral y Setúbal, entre otros). CDP', 4),
('50000000-0000-0000-0000-0000000000000065', 'artes-visuales', 'artes-visuales-en-contexto', 'Manifestaciones artísticas que preservan, modifican o impactan en el paisaje y/o ambiente: land art, street art, intervenciones. EAI', 4),
('50000000-0000-0000-0000-0000000000000066', 'artes-visuales', 'producci-n-visual', 'Creación de imágenes efímeras y permanentes a partir de la observación visual y/o táctil, de la imaginación, de la memoria, el azar y el juego.', 5),
('50000000-0000-0000-0000-0000000000000067', 'artes-visuales', 'producci-n-visual', 'Variados usos de las herramientas, soportes y materiales en una misma producción y en distintas producciones. Selección de materiales, soportes, herramientas y procedimientos según la intención expresiva.', 5),
('50000000-0000-0000-0000-0000000000000068', 'artes-visuales', 'producci-n-visual', 'Posibilidades compositivas y simbólicas de las formas: simétricas/asimétricas, simples/complejas, geométricas, zoomorfas, antropomorfas, “mitoformas”, etcétera. EI', 5),
('50000000-0000-0000-0000-0000000000000069', 'artes-visuales', 'producci-n-visual', 'Extracción de tintes naturales: decocción y machacado de especies vegetales tintóreas. Transformaciones del color a partir de la luz solar: antotipia con tintes naturales. Valoración y cuidado de la biodiversidad en relación con la producción artística. EAI', 5),
('50000000-0000-0000-0000-000000000000006a', 'artes-visuales', 'producci-n-visual', 'Uso expresivo e intencionado del color. Procedimientos que posibilitan la obtención de diferentes tonos: mezcla, superposición de capas, yuxtaposición de pinceladas o manchas. Variaciones del color según el procedimiento pictórico: empaste, aguada, pincel seco, etcétera.', 5),
('50000000-0000-0000-0000-000000000000006b', 'artes-visuales', 'producci-n-visual', 'Creación de texturas visuales mediante la repetición y la combinación de diferentes tipos de formas, líneas, puntos en variadas posiciones y direcciones.', 5),
('50000000-0000-0000-0000-000000000000006c', 'artes-visuales', 'producci-n-visual', 'Relaciones entre las figuras y el espacio que las rodea. Posibilidades expresivas y narrativas que brindan las figuras dispuestas hacia el centro, hacia arriba, hacia abajo y/o saliendo de los límites del soporte.', 5),
('50000000-0000-0000-0000-000000000000006d', 'artes-visuales', 'producci-n-visual', 'Creación de imágenes tridimensionales efímeras y permanentes, desde distintos puntos de partida según la propuesta: observación visual y/o táctil, imaginación, memoria, azar y juego.', 5),
('50000000-0000-0000-0000-000000000000006e', 'artes-visuales', 'producci-n-visual', 'Variados usos de las herramientas y materiales en una misma y en distintas producciones: selección de materiales, herramientas y procedimientos según la intención expresiva.', 5),
('50000000-0000-0000-0000-000000000000006f', 'artes-visuales', 'producci-n-visual', 'Posibilidades expresivas de diversos tipos de formas (orgánicas, geométricas, zoomorfas, antropomorfas) en la creación tridimensional (escultura de bulto, altorrelieve, estatuillas, amuletos, entre otras). EI', 5),
('50000000-0000-0000-0000-0000000000000070', 'artes-visuales', 'producci-n-visual', 'Modelado de arcilla u otras pastas blandas (masa de sal, papel maché u otras). Etapas de la producción escultórica: boceto o idea, estructura o sostén, adición y sustracción del material, pátinas y acabados.', 5),
('50000000-0000-0000-0000-0000000000000071', 'artes-visuales', 'producci-n-visual', 'Exploración de las características y posibilidades que brindan las instalaciones e intervenciones efímeras para resignificar los espacios de la escuela y/o el paisaje de su entorno. Uso y disposición espacial de elementos naturales e industriales según sus posibilidades simbólicas y expresivas.', 5),
('50000000-0000-0000-0000-0000000000000072', 'artes-visuales', 'producci-n-visual', 'Construcción de herramientas gráficas, pictóricas y/o escultóricas a partir de la recuperación de elementos industriales y/o naturales. Exploración de trazos, huellas, manchas e incisiones que posibilitan las herramientas creadas con ramas, lanas, telas, plásticos.', 5),
('50000000-0000-0000-0000-0000000000000073', 'artes-visuales', 'producci-n-visual', 'Arte efímero y arte participativo o de cocreación: posibilidades expresivas y de participación del público en instalaciones bidimensionales, tridimensionales y/o digitales, pizarras interactivas, esculturas móviles y/o desarmables en el espacio escolar.', 5),
('50000000-0000-0000-0000-0000000000000074', 'artes-visuales', 'producci-n-visual', 'Posibilidades narrativas y visuales de lenguajes integrados: la historieta, el fanzine, artzine, arte correo y pósters. Relaciones entre imágenes y palabras. Expresividad de la tipografía y de los formatos y tamaños de los soportes.', 5),
('50000000-0000-0000-0000-0000000000000075', 'artes-visuales', 'apreciaci-n', 'Exploración multisensorial de diferentes espacios, formas, texturas y colores (sensaciones visuales, auditivas, olfativas, táctiles, entre otras). Uso de recursos o instrumentos que expanden la percepción (visores, lupas, ojos cerrados, descripciones sonoras, extensores, desplazamientos, etc.).', 5),
('50000000-0000-0000-0000-0000000000000076', 'artes-visuales', 'apreciaci-n', 'Reconocimiento de distintos usos de los elementos visuales, de los materiales, soportes y herramientas en producciones propias y de pares. Relaciones entre el punto de partida, las intenciones expresivas, las decisiones de proceso y la producción resultante.', 5),
('50000000-0000-0000-0000-0000000000000077', 'artes-visuales', 'apreciaci-n', 'Cualidades estéticas, simbólicas y procedimentales en la cerámica santafesina tradicional y en las producciones actuales con distintas tendencias estéticas. EI', 5),
('50000000-0000-0000-0000-0000000000000078', 'artes-visuales', 'apreciaci-n', 'Simbología, características técnicas y elementos visuales en la alfarería y otras producciones de las culturas Chaná Timbú, Guaraní, y las producciones contemporáneas que retoman las tradiciones de las culturas ancestrales (taller de La Guardia). EI', 5),
('50000000-0000-0000-0000-0000000000000079', 'artes-visuales', 'apreciaci-n', 'Similitudes y diferencias en el uso de los elementos visuales y técnicas en obras tradicionales y contemporáneas de distintos países. Construcción de significados ante diferentes producciones.', 5),
('50000000-0000-0000-0000-000000000000007a', 'artes-visuales', 'apreciaci-n', 'Diversidad estética en la cerámica moderna y contemporánea. Características de forma, textura, color y expresividad en esculturas cerámicas (Leo Tavella, Elba Byron, Renata Petersen, Juliana Frías, Ana Hillar, Kiwi, entre otras posibilidades).', 5),
('50000000-0000-0000-0000-000000000000007b', 'artes-visuales', 'apreciaci-n', 'Participación activa en encuentros presenciales o virtuales con artistas y/o creadores tales como ceramistas, pintores/as, tejedores/as, escultores/as, diseñadores, grabadores, artesanos, escenógrafos y/o mascareros. EI', 5),
('50000000-0000-0000-0000-000000000000007c', 'artes-visuales', 'apreciaci-n', 'Las producciones tridimensionales y sus relaciones con los espacios de emplazamiento. Reconocimiento de puntos de apoyo y espacios que rodean, contienen y/o atraviesan a las obras.', 5),
('50000000-0000-0000-0000-000000000000007d', 'artes-visuales', 'artes-visuales-en-contexto', 'Museos de arte, etnográficos y/o arqueológicos como espacios de aproximación a las culturas del pasado. El museo como ámbito de resguardo de la memoria, de costumbres y de saberes del pasado y del presente. CDP, EI', 5),
('50000000-0000-0000-0000-000000000000007e', 'artes-visuales', 'artes-visuales-en-contexto', 'Recursos de exhibición y cuidado de las producciones propias y de pares en el ámbito escolar: elecciones grupales sobre la disposición de las creaciones, construcción de títulos y textos breves, recursos de accesibilidad, entre otras posibilidades. CDP', 5),
('50000000-0000-0000-0000-000000000000007f', 'artes-visuales', 'artes-visuales-en-contexto', 'Recursos de accesibilidad que permiten la interacción de todas las personas con las obras de arte (audioguías, réplicas para la percepción táctil, audiodescripciones y otros).', 5),
('50000000-0000-0000-0000-0000000000000080', 'artes-visuales', 'artes-visuales-en-contexto', 'El modelado y la cerámica en las culturas prehispánicas. “Campanas” de las culturas Chaná-Timbú (grupos canoeros del litoral); sus funciones estéticas y utilitarias. EI', 5),
('50000000-0000-0000-0000-0000000000000081', 'artes-visuales', 'artes-visuales-en-contexto', 'La cerámica utilitaria: características de la producción artesanal y de la producción industrial. Similitudes y diferencias en las intenciones estéticas y técnicas.', 5),
('50000000-0000-0000-0000-0000000000000082', 'artes-visuales', 'artes-visuales-en-contexto', 'El modelado, la cerámica y otras prácticas escultóricas en la actualidad. Origen de los materiales escultóricos: naturales (arcilla, piedra, metales, etc.), plásticos, textiles, entre otros. Tecnologías de diferentes épocas y su incidencia en la producción escultórica.', 5),
('50000000-0000-0000-0000-0000000000000083', 'artes-visuales', 'producci-n-visual', 'Creación de imágenes efímeras y permanentes a partir de la observación visual y/o táctil, de la imaginación, de la memoria, el azar y el juego.', 6),
('50000000-0000-0000-0000-0000000000000084', 'artes-visuales', 'producci-n-visual', 'Variados usos de las herramientas, soportes y materiales en una misma producción y en distintas producciones. Selección de materiales, soportes, herramientas y procedimientos según la intención expresiva.', 6),
('50000000-0000-0000-0000-0000000000000085', 'artes-visuales', 'producci-n-visual', 'Recursos de estilización en la representación de la figura humana (geometrización, ensanchamiento, alargamiento, síntesis, etc.), en grabados, dibujos, pinturas y/o collage, entre otras posibilidades.', 6),
('50000000-0000-0000-0000-0000000000000086', 'artes-visuales', 'producci-n-visual', 'Variaciones tonales con intención descriptiva y con intención imaginativa. Mezclas pigmentarias. Mezclas de color por superposición de capas de materiales secos (lápices, tizas, papeles traslúcidos, etc.) y de materiales fluidos (acuarelas, tintas, etc.).', 6),
('50000000-0000-0000-0000-0000000000000087', 'artes-visuales', 'producci-n-visual', 'Texturas táctiles y visuales como descripción y/o como reinvención de las superficies representadas. Creación y uso de herramientas para la obtención de texturas: sellos, rodillos, pinceles no convencionales, etcétera.', 6),
('50000000-0000-0000-0000-0000000000000088', 'artes-visuales', 'producci-n-visual', 'Relaciones figura-fondo: simples, complejas, con particiones del espacio, con ilusiones de profundidad, con superposición de imágenes, etcétera.', 6),
('50000000-0000-0000-0000-0000000000000089', 'artes-visuales', 'producci-n-visual', 'Creación de imágenes tridimensionales efímeras y permanentes, desde distintos puntos de partida según la propuesta: observación visual y/o táctil, imaginación, memoria, azar y juego.', 6),
('50000000-0000-0000-0000-000000000000008a', 'artes-visuales', 'producci-n-visual', 'Variados usos de las herramientas y materiales en una misma y en distintas producciones: selección de materiales, herramientas y procedimientos según la intención expresiva.', 6),
('50000000-0000-0000-0000-000000000000008b', 'artes-visuales', 'producci-n-visual', 'Relaciones entre las formas y el espacio en esculturas y/o instalaciones: volúmenes macizos y huecos, espacios que rodean, contienen o atraviesan las formas.', 6),
('50000000-0000-0000-0000-000000000000008c', 'artes-visuales', 'producci-n-visual', 'Procedimientos escultóricos sobre el propio cuerpo como soporte: ensamble de diferentes materiales en la creación de máscaras, vestuarios u ornamentos, entre otras posibilidades.', 6),
('50000000-0000-0000-0000-000000000000008d', 'artes-visuales', 'producci-n-visual', 'Selección y combinación de elementos naturales e industriales (hojas, plumas, textiles, plásticos, etc.), en esculturas y/o creaciones sobre el propio cuerpo, según sus características de peso, masa, opacidad/transparencia, etcétera.', 6),
('50000000-0000-0000-0000-000000000000008e', 'artes-visuales', 'producci-n-visual', 'Construcción de herramientas gráficas, pictóricas y/o escultóricas a partir de la recuperación de elementos industriales y/o naturales. Exploración de trazos, huellas, manchas e incisiones que posibilitan las herramientas creadas con ramas, lanas, telas, plásticos.', 6),
('50000000-0000-0000-0000-000000000000008f', 'artes-visuales', 'producci-n-visual', 'Recreación y resignificación de retratos mediante el fotomontaje, la intervención de fotografías y/o reproducciones de obras propias y/o de diferentes artistas. Recursos plásticos y/o digitales que transforman la gestualidad y expresividad de la/s persona/s representadas.', 6),
('50000000-0000-0000-0000-0000000000000090', 'artes-visuales', 'producci-n-visual', 'Posibilidades narrativas y expresivas de lenguajes integrados: el libro de artista, diario de artista, arte correo u otras prácticas editoriales. Recursos de creación y de intervención de publicaciones en desuso (dibujo, estampado, bordado, calado, entre otros).', 6),
('50000000-0000-0000-0000-0000000000000091', 'artes-visuales', 'apreciaci-n', 'Exploración multisensorial de diferentes espacios, formas, texturas y colores (sensaciones visuales, auditivas, olfativas, táctiles, entre otras). Uso de recursos o instrumentos que expanden la percepción (visores, lupas, ojos cerrados, descripciones sonoras, extensores, desplazamientos, etc.).', 6),
('50000000-0000-0000-0000-0000000000000092', 'artes-visuales', 'apreciaci-n', 'Reconocimiento de distintos usos de los elementos visuales, de los materiales, soportes y herramientas en producciones propias y de pares. Relaciones entre el punto de partida, las intenciones expresivas, las decisiones de proceso y la producción resultante.', 6),
('50000000-0000-0000-0000-0000000000000093', 'artes-visuales', 'apreciaci-n', 'Percepción multisensorial y valoración de características del propio cuerpo y del de pares. ESI Representaciones de los cuerpos en el arte y la publicidad: estereotipos, modelos de belleza; reflexión sobre sus impactos y consecuencias. ESI', 6),
('50000000-0000-0000-0000-0000000000000094', 'artes-visuales', 'apreciaci-n', 'Reconocimiento de diversas intenciones expresivas y elementos visuales en las obras de retratistas santafesinos (César López Claro, Gustavo Cochet, entre otros/as). Identificación de puntos de vista (frente, perfil, busto, cuerpo entero, etc.), de tonos, saturaciones y valores en las paletas de color y de formas naturalistas o estilizadas.', 6),
('50000000-0000-0000-0000-0000000000000095', 'artes-visuales', 'apreciaci-n', 'Reconocimiento de relaciones entre obras del pasado y del presente de distintos países: comparación de técnicas y usos de elementos del lenguaje visual. Construcción de significados ante diferentes producciones.', 6),
('50000000-0000-0000-0000-0000000000000096', 'artes-visuales', 'apreciaci-n', 'Diversidad estética en retratos pintados, esculpidos, impresos, fotografiados y/o dibujados. Identificación de recursos de representación y estilización en retratos clásicos, modernos y contemporáneos. Identificación de grupos sociales retratados en producciones artísticas y objetos cotidianos: obras de arte, billetes, medallas, remeras, entre otros.', 6),
('50000000-0000-0000-0000-0000000000000097', 'artes-visuales', 'apreciaci-n', 'Participación activa en encuentros presenciales o virtuales con artistas y/o creadores tales como ceramistas, pintores/as, tejedores/as, escultores/as, diseñadores, grabadores, artesanos, escenógrafos y/o mascareros. EI', 6),
('50000000-0000-0000-0000-0000000000000098', 'artes-visuales', 'apreciaci-n', 'La figura humana en diversos tipos de obras. Reconocimiento de similitudes y diferencias en los cánones de belleza implicados en la representación artística de los cuerpos.', 6),
('50000000-0000-0000-0000-0000000000000099', 'artes-visuales', 'artes-visuales-en-contexto', 'Los medios de comunicación, el ciberespacio y las redes sociales como ámbitos de difusión de las producciones visuales. Criterios de exhibición y visionado responsable y cuidadoso hacia sí mismos/as y hacia la comunidad. ECD', 6),
('50000000-0000-0000-0000-000000000000009a', 'artes-visuales', 'artes-visuales-en-contexto', 'Recursos de exhibición y cuidado de las producciones propias y de pares en el ámbito escolar: elecciones grupales sobre la disposición de las creaciones, construcción de títulos y textos breves, recursos de accesibilidad, entre otras posibilidades. CDP', 6),
('50000000-0000-0000-0000-000000000000009b', 'artes-visuales', 'artes-visuales-en-contexto', 'Recursos estéticos e interactivos que se emplean en las plataformas digitales para publicar producciones artísticas, anuncios, fotografías y otros tipos de imágenes.', 6),
('50000000-0000-0000-0000-000000000000009c', 'artes-visuales', 'artes-visuales-en-contexto', 'El retrato y autorretrato en la pintura, la escultura, el dibujo, el grabado y la fotografía. Funciones del retrato: homenaje, alegoría, memoria, entre otras.', 6),
('50000000-0000-0000-0000-000000000000009d', 'artes-visuales', 'artes-visuales-en-contexto', 'El cuerpo como imagen y soporte. Características y funciones culturales de las máscaras, vestuarios y joyería en prácticas artísticas y festividades populares. ESI, EI', 6),
('50000000-0000-0000-0000-000000000000009e', 'artes-visuales', 'producci-n-visual', 'Resignificación de imágenes y fragmentos (fotografías, publicidades, mapas, etc.). Selección de formas, colores, texturas y figuraciones para diferentes creaciones: publicidades de ficción, afiches de películas, fanzines, etc. Posibilidades estéticas y narrativas que brindan las diferentes tipografías, las gamas de color, los contrastes de tamaño, tonalidad y textura.', 7),
('50000000-0000-0000-0000-000000000000009f', 'artes-visuales', 'producci-n-visual', 'La organización en la composición en imágenes figurativas y no figurativas: espacios llenos y vacíos.', 7),
('50000000-0000-0000-0000-00000000000000a0', 'artes-visuales', 'producci-n-visual', 'Diversas organizaciones espaciales de los soportes: particiones, viñetas.', 7),
('50000000-0000-0000-0000-00000000000000a1', 'artes-visuales', 'producci-n-visual', 'Relación forma, color, palabra y sentido en creaciones que combinan el lenguaje visual y verbal.', 7),
('50000000-0000-0000-0000-00000000000000a2', 'artes-visuales', 'producci-n-visual', 'Noción y uso del boceto para la construcción de proyectos grupales. Los bocetos como apuntes gráficos y/o fotográficos de ideas iniciales necesarios para diseñar las producciones multimediales y/o performáticas.', 7),
('50000000-0000-0000-0000-00000000000000a3', 'artes-visuales', 'producci-n-visual', 'Exploración de las posibilidades metafóricas de diversos elementos y espacios cotidianos y sus combinaciones. Relaciones espaciales y de sentido entre objetos y elementos naturales: juntos, distanciados, dentro de, encima de, etcétera.', 7),
('50000000-0000-0000-0000-00000000000000a4', 'artes-visuales', 'producci-n-visual', 'Artes performáticas: diseño de acciones, movimientos, intervenciones del o con el público. Posibilidades narrativas que brinda la visualidad de los gestos, las sombras, los desplazamientos en articulación con la sonoridad y el espacio. Performances en vivo y/o documentadas mediante registros videográficos.', 7),
('50000000-0000-0000-0000-00000000000000a5', 'artes-visuales', 'apreciaci-n', 'Análisis de relaciones entre los usos de elementos visuales, materiales, soportes y herramientas y las intenciones expresivas durante el proceso de creación propia o grupal y en la producción finalizada.', 7),
('50000000-0000-0000-0000-00000000000000a6', 'artes-visuales', 'apreciaci-n', 'Identificación de recursos visuales y comunicativos en la imagen publicitaria y el diseño: tipografías, isologotipos, viñetas y otros recursos en afiches y/o publicaciones.', 7),
('50000000-0000-0000-0000-00000000000000a7', 'artes-visuales', 'apreciaci-n', 'Reconocimiento de recursos visuales en interacción con otros elementos sonoros, expresivos y técnicos utilizados en producciones performáticas locales: carnavales, fiestas populares, teatro callejero, esculturas “vivas”, entre otras. EI', 7),
('50000000-0000-0000-0000-00000000000000a8', 'artes-visuales', 'apreciaci-n', 'Búsqueda de información sobre las manifestaciones performáticas locales del presente y del pasado: las fotografías, las entrevistas y los diálogos con familias e instituciones históricas como fuentes de información para conocer manifestaciones artísticas patrimoniales.', 7),
('50000000-0000-0000-0000-00000000000000a9', 'artes-visuales', 'apreciaci-n', 'Identificación de recursos gráficos, narrativos y estilísticos en la ilustración presente en libros, historietas, afiches, estampillas, sitios digitales, dibujos animados, billetes, indumentaria, juegos y juguetes. CDP', 7),
('50000000-0000-0000-0000-00000000000000aa', 'artes-visuales', 'apreciaci-n', 'Estrategias apreciativas para conocer y/o participar en producciones artísticas performáticas: distinción entre la observación directa y/o participativa y la observación indirecta a través de registros fotográficos o videográficos. Observación indirecta de obras performáticas de diferentes artistas y grupos artísticos. CDP', 7),
('50000000-0000-0000-0000-00000000000000ab', 'artes-visuales', 'artes-visuales-en-contexto', 'Exhibiciones interactivas y multimediales dentro y fuera de la escuela. Sistemas expositivos para producciones interdisciplinarias. Activación de múltiples sentidos, sensaciones y participaciones en muestras inmersivas y/o de cruces entre diferentes lenguajes artísticos (visual, musical o sonoro, videodanza u otros). CDP', 7),
('50000000-0000-0000-0000-00000000000000ac', 'artes-visuales', 'artes-visuales-en-contexto', 'La noción y la vivencia del montaje como instancia creativa que permite hacer pública la creación visual: disposición de las obras, iluminación, títulos y textos, entre otros. Selección, clasificación, agrupamientos, relación entre las partes y el todo.', 7),
('50000000-0000-0000-0000-00000000000000ad', 'artes-visuales', 'artes-visuales-en-contexto', 'Creaciones visuales vinculadas al proceso editorial: libro de artista, libro objeto, fanzines, artzines, historietas, entre otras. La invención de la imprenta, de los medios digitales y de las impresoras, y su relación con la expansión del campo de las artes visuales.', 7),
('50000000-0000-0000-0000-00000000000000ae', 'artes-visuales', 'artes-visuales-en-contexto', 'Las artes multimediales: características básicas y sus relaciones con el cine, el video, la tecnología digital, la programación y/o la electrónica. Noción de trabajo interdisciplinario en la producción artística. CDP y ECD', 7),
('50000000-0000-0000-0000-00000000000000af', 'artes-visuales', 'artes-visuales-en-contexto', 'La performance como práctica artística en la que se integran la imagen, el movimiento, el sonido y la acción corporal. Relaciones y combinaciones con elementos del teatro, la música, entre otras posibilidades. Noción de performance como acontecimiento artístico basado en la acción (guionada o improvisada) y la participación o contacto directo con el público. ESI', 7)
